var data = [["May 18",3.07],["May 19",-0.82],["May 20",-8.82],["May 21",-1.94],["May 22",0.26],["May 26",-2.81],["May 27",-5.55],["May 28",0.25],["May 29",-1.73],["Jun 01",5.49],["Jun 02",1.74],["Jun 03",2.41],["Jun 04",-3.1],["Jun 05",-2.69],["Jun 08",0.84],["Jun 09",-3.4],["Jun 10",2.07],["Jun 11",-2.58],["Jun 12",-3.23],["Jun 14",-4.59],["Jun 15",-0.28],["Jun 16",-6.79],["Jun 17",1.0],["Jun 18",-2.58]];
var n = data.length;
var W = 680, H = 300, margin = {left:62, right:24, top:18, bottom:46};
var PW = W - margin.left - margin.right, PH = H - margin.top - margin.bottom;
var yMin = -10, yMax = 7;
function xS(i){ return margin.left + (i/(n-1))*PW; }
function yS(v){ return margin.top + ((yMax - v)/(yMax - yMin))*PH; }
var svg = document.createElementNS("http://www.w3.org/2000/svg", "svg");
svg.setAttribute("viewBox", "0 0 680 300");
svg.setAttribute("width", "100%");
var y0 = yS(0);
svg.appendChild(el("line", {x1:margin.left, x2:margin.left+PW, y1:y0, y2:y0, stroke:"#d8d8d8", "stroke-width":"1"}));
var yTicks = [-8,-4,0,4];
for (var t=0; t<yTicks.length; t++){
  var ty = yS(yTicks[t]);
  svg.appendChild(el("line", {x1:margin.left, x2:margin.left+PW, y1:ty, y2:ty, stroke:"#ececec", "stroke-width":"0.5"}));
