svg.appendChild(el("text", {x:xS(maxIdx), y:yS(maxPt[1])-8, "text-anchor":"middle", "font-size":"8", "font-weight":"700", fill:"#3a7a55", "font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, "+5.49% JUN 1"));
