svg.appendChild(el("text", {x:noteX, y:yS(5)-22, "text-anchor":"start", "font-size":"8", fill:"#444", "font-family":"-apple-system,BlinkMacSystemFont,Roboto,Helvetica,Arial,sans-serif"}, "CORP. PERTINENT LOAN RATE"));
